insert into profils_metier (id, nom, config) values ('immobilier', 'Agence immobilière', '{"contexte": "Agence immobilière de 3 à 30 collaborateurs. Les négociateurs gèrent des mandats de vente et de location, publient des annonces sur plusieurs portails, organisent des visites et relancent les prospects.", "logiciels_habituels": ["Logiciel de transaction (fiches mandats)", "Portails d''annonces", "Messagerie", "Excel ou Google Sheets", "Agenda"], "taches_typiques": ["Multidiffusion d''annonces", "Relance des prospects après visite", "Saisie des mandats", "Comptes rendus de visite", "Prise de rendez-vous"], "motifs_a_flouter": [{"nom": "telephone", "regex": "(?:\\+33\\s?|0)[1-9](?:[\\s.-]?\\d{2}){4}", "remplacement": "[TELEPHONE]"}, {"nom": "email", "regex": "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}", "remplacement": "[EMAIL]"}, {"nom": "montant", "regex": "\\d[\\d\\s.,]*\\s?(?:€|EUR|euros?)", "remplacement": "[MONTANT]"}, {"nom": "iban", "regex": "\\bFR\\d{2}(?:\\s?[A-Z0-9]{4}){5}\\s?[A-Z0-9]{3}\\b", "remplacement": "[IBAN]"}], "entites_a_flouter": ["PER"], "champs_jamais_stockes": ["Coordonnées des prospects et propriétaires", "Budget et situation financière des prospects", "Pièces d''identité et justificatifs"], "conservation_jours": 30, "prompt_systeme": "Tu analyses l''activité d''un collaborateur d''agence immobilière. Le vocabulaire clé : mandat, multidiffusion, portail, visite, prospect, compromis. Les données personnelles ont été remplacées par des marqueurs comme [NOM] ou [TELEPHONE] : ne tente jamais de les deviner ni de les reconstituer, et n''en reprends aucune dans ta réponse. Concentre-toi sur les enchaînements de tâches répétitifs et le temps qu''ils prennent."}'::jsonb) on conflict (id) do nothing;
insert into profils_metier (id, nom, config) values ('comptable', 'Cabinet d''expertise comptable', '{"contexte": "Cabinet de 5 à 50 collaborateurs. Les collaborateurs saisissent des pièces, relancent les clients pour les justificatifs manquants, font des rapprochements bancaires et préparent des déclarations. Ils sont tenus au secret professionnel.", "logiciels_habituels": ["Logiciel de production comptable", "Outil de collecte de pièces", "Banque en ligne", "Messagerie", "Excel"], "taches_typiques": ["Saisie des factures", "Relance des pièces manquantes", "Rapprochement bancaire", "Préparation des déclarations de TVA"], "motifs_a_flouter": [{"nom": "telephone", "regex": "(?:\\+33\\s?|0)[1-9](?:[\\s.-]?\\d{2}){4}", "remplacement": "[TELEPHONE]"}, {"nom": "email", "regex": "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}", "remplacement": "[EMAIL]"}, {"nom": "montant", "regex": "\\d[\\d\\s.,]*\\s?(?:€|EUR|euros?)", "remplacement": "[MONTANT]"}, {"nom": "iban", "regex": "\\bFR\\d{2}(?:\\s?[A-Z0-9]{4}){5}\\s?[A-Z0-9]{3}\\b", "remplacement": "[IBAN]"}, {"nom": "siren_siret", "regex": "\\b\\d{3}\\s?\\d{3}\\s?\\d{3}(?:\\s?\\d{5})?\\b", "remplacement": "[SIREN]"}, {"nom": "numero_secu", "regex": "\\b[12]\\s?\\d{2}\\s?\\d{2}\\s?\\d{2}\\s?\\d{3}\\s?\\d{3}\\s?\\d{2}\\b", "remplacement": "[NUMERO_SECU]"}], "entites_a_flouter": ["PER", "ORG"], "champs_jamais_stockes": ["Montants et soldes", "IBAN et coordonnées bancaires", "Noms et identifiants des clients du cabinet", "Numéros de sécurité sociale"], "conservation_jours": 15, "prompt_systeme": "Tu analyses l''activité d''un collaborateur de cabinet d''expertise comptable, tenu au secret professionnel. Le vocabulaire clé : pièce, saisie, lettrage, rapprochement, TVA, liasse, relance. Les montants, IBAN, noms et identifiants ont été remplacés par des marqueurs : ne tente jamais de les deviner ni de les reconstituer, et n''en reprends aucun dans ta réponse. Concentre-toi sur les enchaînements de tâches répétitifs et le temps qu''ils prennent."}'::jsonb) on conflict (id) do nothing;
insert into profils_metier (id, nom, config) values ('avocat', 'Cabinet d''avocats', '{"contexte": "Cabinet d''avocats. Les collaborateurs gèrent des dossiers, des échéances de procédure, des courriers et la facturation au temps passé. Le secret professionnel est absolu.", "logiciels_habituels": ["Logiciel de gestion de cabinet", "Traitement de texte", "Messagerie", "Agenda", "Plateformes de procédure"], "taches_typiques": ["Suivi des échéances", "Saisie des temps passés", "Mise en forme de courriers types", "Classement des pièces"], "motifs_a_flouter": [{"nom": "telephone", "regex": "(?:\\+33\\s?|0)[1-9](?:[\\s.-]?\\d{2}){4}", "remplacement": "[TELEPHONE]"}, {"nom": "email", "regex": "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}", "remplacement": "[EMAIL]"}, {"nom": "montant", "regex": "\\d[\\d\\s.,]*\\s?(?:€|EUR|euros?)", "remplacement": "[MONTANT]"}, {"nom": "numero_dossier", "regex": "\\b(?:RG|N°)\\s?\\d{2}[/-]\\d{3,6}\\b", "remplacement": "[DOSSIER]"}], "entites_a_flouter": ["PER", "ORG", "LOC"], "champs_jamais_stockes": ["Noms des parties et des clients", "Contenu des dossiers et des courriers", "Numéros de dossier"], "conservation_jours": 7, "prompt_systeme": "Tu analyses l''activité d''un collaborateur de cabinet d''avocats, soumis au secret professionnel absolu. Ne reprends jamais le contenu d''un dossier, d''un courrier ou le nom d''une partie : décris uniquement la forme des tâches (quel logiciel, quel enchaînement, combien de temps). Les données sensibles ont été remplacées par des marqueurs : ne tente jamais de les deviner ni de les reconstituer."}'::jsonb) on conflict (id) do nothing;
